uint32_t Bsim4vaGenModel::numInternalNodes() const {
    uint32_t count = 0;
    if (rfsim_bsim4_eff_rdsmod(rdsmod_) != 0.0) count += 2;  // di, si
    if (rfsim_bsim4_eff_rgatemod(rgatemod_) != 0.0) count += 2;  // gi, gm
    if (rfsim_bsim4_eff_rbodymod(rbodymod_) != 0.0) count += 3;  // bi, sbulk, dbulk
    count += 7;  // branch nodes
    return count;
}

void Bsim4vaGenModel::allocateInternalNodes(NodeId& internalNodeBase) {
    bool needDiSi = (rfsim_bsim4_eff_rdsmod(rdsmod_) != 0.0);
    bool needGiGm = (rfsim_bsim4_eff_rgatemod(rgatemod_) != 0.0);
    bool needBody = (rfsim_bsim4_eff_rbodymod(rbodymod_) != 0.0);
    // di 折叠目标：本模型端口顺序 d,g,s,b（nodes_[0]=d）。
    // （历史 bug：误写 nodes_[1]=g —— 照抄 bsimsoi 的端口顺序所致，
    //   会使本征漏极接栅极，放大器退化为二极管连接、增益恒为 1）
    if (needDiSi) nodes_[4] = internalNodeBase++; else nodes_[4] = nodes_[0];
    if (needDiSi) nodes_[5] = internalNodeBase++; else nodes_[5] = nodes_[2];
    if (needGiGm) nodes_[6] = internalNodeBase++; else nodes_[6] = nodes_[1];
    if (needGiGm) nodes_[7] = internalNodeBase++; else nodes_[7] = nodes_[1];
    if (needBody) nodes_[8] = internalNodeBase++; else nodes_[8] = nodes_[3];
    if (needBody) nodes_[9] = internalNodeBase++; else nodes_[9] = nodes_[3];
    if (needBody) nodes_[10] = internalNodeBase++; else nodes_[10] = nodes_[3];
    nodes_[11] = internalNodeBase++;  // _br2_5
    nodes_[12] = internalNodeBase++;  // _br0_4
    nodes_[13] = internalNodeBase++;  // _br1_7
    nodes_[14] = internalNodeBase++;  // _br7_6
    nodes_[15] = internalNodeBase++;  // _br9_3
    nodes_[16] = internalNodeBase++;  // _br3_8
    nodes_[17] = internalNodeBase++;  // _br3_10
}

